## 2. 타입 정의

### `src/types/notification.ts`

```ts
export type Channel = 'email' | 'sms' | 'push';

export interface NotificationRequest {
  channel: Channel;
  to: string;
  subject?: string;
  message: string;
}

export interface NotificationResult {
  provider: string;
  success: boolean;
  messageId?: string;
  error?: string;
}
```

---

## 3. Provider 인터페이스

### `src/providers/provider.interface.ts`

```ts
import { NotificationRequest, NotificationResult, Channel } from '../types/notification';

export interface Provider {
  readonly name: string;
  supports(channel: Channel): boolean;
  send(request: NotificationRequest): Promise<NotificationResult>;
}
```

이 구조의 장점은:

- 모든 provider가 동일한 계약을 따름
- router는 구체 구현이 아니라 인터페이스에만 의존
- provider 추가가 쉬움

---

## 4. Provider 구현체들

### `src/providers/email.provider.ts`

```ts
import { Provider } from './provider.interface';
import { NotificationRequest, NotificationResult, Channel } from '../types/notification';

export class EmailProvider implements Provider {
  public readonly name = 'email-provider';

  supports(channel: Channel): boolean {
    return channel === 'email';
  }

  async send(request: NotificationRequest): Promise<NotificationResult> {
    if (!request.subject) {
      return {
        provider: this.name,
        success: false,
        error: 'Email requires subject',
      };
    }

    // 실제 구현에서는 외부 이메일 API 호출
    return {
      provider: this.name,
      success: true,
      messageId: `email-${Date.now()}`,
    };
  }
}
```

### `src/providers/sms.provider.ts`

```ts
import { Provider } from './provider.interface';
import { NotificationRequest, NotificationResult, Channel } from '../types/notification';

export class SmsProvider implements Provider {
  public readonly name = 'sms-provider';

  supports(channel: Channel): boolean {
    return channel === 'sms';
  }

  async send(request: NotificationRequest): Promise<NotificationResult> {
    if (request.message.length > 160) {
      return {
        provider: this.name,
        success: false,
        error: 'SMS message too long',
      };
    }

    // 실제 구현에서는 외부 SMS API 호출
    return {
      provider: this.name,
      success: true,
      messageId: `sms-${Date.now()}`,
    };
  }
}
```

### `src/providers/push.provider.ts`

```ts
import { Provider } from './provider.interface';
import { NotificationRequest, NotificationResult, Channel } from '../types/notification';

export class PushProvider implements Provider {
  public readonly name = 'push-provider';

  supports(channel: Channel): boolean {
    return channel === 'push';
  }

  async send(request: NotificationRequest): Promise<NotificationResult> {
