## 5. Provider Router 구현

### `src/providers/provider-router.ts`

```ts
import { Provider } from './provider.interface';
import { NotificationRequest } from '../types/notification';

export class ProviderRouter {
  constructor(private readonly providers: Provider[]) {}

  getProvider(request: NotificationRequest): Provider {
    const provider = this.providers.find((p) => p.supports(request.channel));

    if (!provider) {
      throw new Error(`No provider found for channel: ${request.channel}`);
    }

    return provider;
  }

  async route(request: NotificationRequest) {
    const provider = this.getProvider(request);
    return provider.send(request);
  }
}
```

