# 1) 타입 및 에러 정의

```ts
// ai-types.ts
export type AIMessage = {
  role: "system" | "user" | "assistant";
  content: string;
};

export type AIRequest = {
  messages: AIMessage[];
  temperature?: number;
  maxTokens?: number;
  requestId?: string;
  metadata?: Record<string, string>;
};

export type AIResponse = {
  provider: string;
  model: string;
  content: string;
  usage?: {
    inputTokens?: number;
    outputTokens?: number;
    totalTokens?: number;
  };
  latencyMs: number;
};

export type AIProviderResult = AIResponse;

export interface AIProvider {
  name: string;
  model: string;
  generate(request: AIRequest): Promise<AIProviderResult>;
}

export type ErrorCode =
  | "TIMEOUT"
  | "RATE_LIMIT"
  | "AUTH"
  | "BAD_REQUEST"
  | "SERVER_ERROR"
  | "NETWORK"
  | "INVALID_RESPONSE"
  | "UNKNOWN";

export class AIError extends Error {
  public readonly code: ErrorCode;
  public readonly provider: string;
  public readonly retryable: boolean;
  public readonly fallbackable: boolean;
  public readonly cause?: unknown;
  public readonly statusCode?: number;

  constructor(params: {
    message: string;
    code: ErrorCode;
    provider: string;
    retryable: boolean;
    fallbackable: boolean;
    cause?: unknown;
    statusCode?: number;
  }) {
    super(params.message);
    this.name = "AIError";
    this.code = params.code;
    this.provider = params.provider;
    this.retryable = params.retryable;
    this.fallbackable = params.fallbackable;
    this.cause = params.cause;
    this.statusCode = params.statusCode;
  }
}

export class AggregateAIError extends Error {
  public readonly errors: AIError[];

  constructor(errors: AIError[]) {
    super(
      `All AI providers failed: ${errors
        .map((e) => `${e.provider}:${e.code}`)
        .join(", ")}`
    );
    this.name = "AggregateAIError";
    this.errors = errors;
  }
}
```

