# 4) Provider 구현 예시

실제 SDK를 붙일 수도 있지만, 여기서는 **fetch 기반**으로 작성해 두겠습니다.
Node 18+ 기준으로 `fetch` 사용 가능.

## 4-1) OpenAI provider 예시

```ts
// providers/openai-provider.ts
import { AIError, AIProvider, AIRequest, AIResponse } from "../ai-types";

type OpenAIProviderConfig = {
  apiKey: string;
  model: string;
  baseUrl?: string;
};

export class OpenAIProvider implements AIProvider {
  public readonly name = "openai";
  public readonly model: string;
  private readonly apiKey: string;
  private readonly baseUrl: string;

  constructor(config: OpenAIProviderConfig) {
    this.apiKey = config.apiKey;
    this.model = config.model;
    this.baseUrl = config.baseUrl ?? "https://api.openai.com/v1";
  }

  async generate(request: AIRequest): Promise<AIResponse> {
    const startedAt = Date.now();

    let response: Response;
    try {
      response = await fetch(`${this.baseUrl}/chat/completions`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${this.apiKey}`,
          ...(request.requestId ? { "X-Request-Id": request.requestId } : {}),
        },
        body: JSON.stringify({
          model: this.model,
          messages: request.messages,
          temperature: request.temperature ?? 0.2,
          max_tokens: request.maxTokens ?? 512,
        }),
      });
    } catch (cause) {
      throw new AIError({
        message: "Network error while calling OpenAI",
        code: "NETWORK",
        provider: this.name,
        retryable: true,
        fallbackable: true,
        cause,
      });
    }

    if (!response.ok) {
      const text = await safeReadText(response);
      throw mapHttpError({
        provider: this.name,
        status: response.status,
        body: text,
      });
    }

    const data = await response.json().catch((cause) => {
      throw new AIError({
        message: "Invalid JSON response from OpenAI",
        code: "INVALID_RESPONSE",
        provider: this.name,
        retryable: false,
        fallbackable: true,
        cause,
      });
    });

    const content = data?.choices?.[0]?.message?.content;
    if (typeof content !== "string") {
      throw new AIError({
        message: "Missing content in OpenAI response",
        code: "INVALID_RESPONSE",
        provider: this.name,
        retryable: false,
        fallbackable: true,
      });
    }

    return {
      provider: this.name,
      model: this.model,
      content,
      usage: {
        inputTokens: data?.usage?.prompt_tokens,
        outputTokens: data?.usage?.completion_tokens,
        totalTokens: data?.usage?.total_tokens,
      },
      latencyMs: Date.now() - startedAt,
    };
  }
}

async function safeReadText(response: Response): Promise<string> {
  try {
    return await response.text();
  } catch {
    return "";
  }
}

function mapHttpError(params: {
  provider: string;
  status: number;
  body?: string;
}): AIError {
  const { provider, status, body } = params;

  if (status === 400) {
    return new AIError({
      message: `Bad request to ${provider}: ${body ?? ""}`,
      code: "BAD_REQUEST",
      provider,
      retryable: false,
      fallbackable: false,
      statusCode: status,
    });
  }

  if (status === 401 || status === 403) {
    return new AIError({
      message: `Authentication error from ${provider}`,
      code: "AUTH",
      provider,
      retryable: false,
      fallbackable: true,
      statusCode: status,
    });
  }

  if (status === 429) {
    return new AIError({
      message: `Rate limited by ${provider}`,
      code: "RATE_LIMIT",
      provider,
      retryable: true,
      fallbackable: true,
      statusCode: status,
    });
  }

  if (status >= 500) {
    return new AIError({
      message: `Server error from ${provider}: ${body ?? ""}`,
      code: "SERVER_ERROR",
      provider,
      retryable: true,
      fallbackable: true,
      statusCode: status,
    });
  }

  return new AIError({
    message: `Unknown error from ${provider}: HTTP ${status} ${body ?? ""}`,
    code: "UNKNOWN",
    provider,
    retryable: false,
    fallbackable: true,
    statusCode: status,
  });
}
```

