// judge/types.ts
export type CandidateModel = "openai" | "claude";
export type JudgeWinner = "A" | "B" | "TIE";
export type FinalWinner = CandidateModel | "tie";

export interface JudgeCriterionScore {
  A: number; // 1-10
  B: number; // 1-10
}

export interface JudgeScores {
  instruction_following: JudgeCriterionScore;
  factuality: JudgeCriterionScore;
  completeness: JudgeCriterionScore;
  safety: JudgeCriterionScore;
  clarity: JudgeCriterionScore;
}

export interface JudgeResult {
  winner: JudgeWinner;
  confidence: number; // 0-1
  scores: JudgeScores;
  reasoning_summary: string;
}

export interface CandidateResponse {
  model: CandidateModel;
  content: string;
}

export interface JudgeInput {
  userPrompt: string;
  openaiResponse: string;
  claudeResponse: string;
  taskContext?: string;
}

export interface FinalJudgement {
  winner: FinalWinner;
  confidence: number;
  rationale: string;
  normalizedScores: {
    openai: number;
    claude: number;
  };
  raw: {
    forward: JudgeResult;
    reverse: JudgeResult;
  };
}
