---

## 1) 핵심 아이디어

흐름은 보통 이렇게 갑니다.

1. 여러 provider에 동시에 요청
2. 각 provider 응답을 정규화
3. scoreboard 규칙으로 점수 계산
4. 최고 점수 provider를 winner로 선택
5. 동점이면 tie-breaker 적용

---

## 2) TypeScript 코드

```ts
// scoreboard-winner.ts

type ProviderName = "openai" | "anthropic" | "google" | "fallback";

export interface ProviderRequest {
  prompt: string;
  maxTokens?: number;
  temperature?: number;
  timeoutMs?: number;
}

export interface ProviderResponse {
  provider: ProviderName;
  content: string;
  latencyMs: number;
  tokenUsage?: {
    input: number;
    output: number;
    total: number;
  };
  model?: string;
  success: boolean;
  error?: string;
  metadata?: Record<string, unknown>;
}

export interface Provider {
  name: ProviderName;
  invoke(request: ProviderRequest): Promise<ProviderResponse>;
}

export interface ScoreBreakdown {
  provider: ProviderName;
  totalScore: number;
  criteria: Record<string, number>;
  reasons: string[];
}

export interface WinnerResult {
  winner: ProviderResponse | null;
  scoreboard: ScoreBreakdown[];
  allResponses: ProviderResponse[];
}

export interface ScoringContext {
  request: ProviderRequest;
  response: ProviderResponse;
}

export interface ScoringRule {
  name: string;
  weight: number;
  evaluate(ctx: ScoringContext): {
    score: number; // 0 ~ 1 권장
    reason?: string;
  };
}

export interface WinnerSelectorOptions {
  providers: Provider[];
  rules: ScoringRule[];
  timeoutMs?: number;
  tieBreaker?: (a: ProviderResponse, b: ProviderResponse) => ProviderResponse;
}

/**
 * 공통 timeout wrapper
 */
async function withTimeout<T>(promise: Promise<T>, timeoutMs: number, errorMessage: string): Promise<T> {
  let timer: NodeJS.Timeout | undefined;

  const timeoutPromise = new Promise<T>((_, reject) => {
    timer = setTimeout(() => {
      reject(new Error(errorMessage));
    }, timeoutMs);
  });

  try {
    return await Promise.race([promise, timeoutPromise]);
  } finally {
    if (timer) clearTimeout(timer);
  }
}

/**
 * provider 호출을 안전하게 감싸는 함수
 */
async function invokeProviderSafely(
  provider: Provider,
  request: ProviderRequest,
  timeoutMs: number
): Promise<ProviderResponse> {
  const startedAt = Date.now();

  try {
    const response = await withTimeout(
      provider.invoke(request),
      timeoutMs,
      `Provider ${provider.name} timed out after ${timeoutMs}ms`
    );

    return {
      ...response,
      provider: provider.name,
      latencyMs: response.latencyMs ?? Date.now() - startedAt,
      success: response.success ?? true,
    };
  } catch (error) {
    return {
      provider: provider.name,
      content: "",
      latencyMs: Date.now() - startedAt,
      success: false,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

/**
 * scoreboard 계산
 */
export function scoreResponse(
  request: ProviderRequest,
  response: ProviderResponse,
  rules: ScoringRule[]
): ScoreBreakdown {
  const criteria: Record<string, number> = {};
  const reasons: string[] = [];

  let totalScore = 0;

  for (const rule of rules) {
    const result = rule.evaluate({ request, response });

    // score는 0~1 범위로 clamp
    const normalized = Math.max(0, Math.min(1, result.score));
    const weighted = normalized * rule.weight;

    criteria[rule.name] = weighted;
    totalScore += weighted;

    if (result.reason) {
      reasons.push(`[${rule.name}] ${result.reason}`);
    }
  }

  return {
    provider: response.provider,
    totalScore,
    criteria,
    reasons,
  };
}

/**
 * winner 선택
 */
export async function selectWinner(
  request: ProviderRequest,
  options: WinnerSelectorOptions
): Promise<WinnerResult> {
  const timeoutMs = options.timeoutMs ?? request.timeoutMs ?? 10_000;

  const responses = await Promise.all(
    options.providers.map((provider) => invokeProviderSafely(provider, request, timeoutMs))
  );

  const scoreboard = responses.map((response) =>
    scoreResponse(request, response, options.rules)
  );

  const responseByProvider = new Map<ProviderName, ProviderResponse>(
    responses.map((r) => [r.provider, r])
  );

  const sorted = [...scoreboard].sort((a, b) => b.totalScore - a.totalScore);

  if (sorted.length === 0) {
    return {
      winner: null,
      scoreboard: [],
      allResponses: [],
    };
  }

  const top = sorted[0];
  const tied = sorted.filter((s) => s.totalScore === top.totalScore);

  let winner: ProviderResponse | null = null;

  if (tied.length === 1) {
    winner = responseByProvider.get(top.provider) ?? null;
  } else {
    const tiedResponses = tied
      .map((s) => responseByProvider.get(s.provider))
      .filter((r): r is ProviderResponse => Boolean(r));

    if (tiedResponses.length === 0) {
      winner = null;
    } else if (tiedResponses.length === 1) {
      winner = tiedResponses[0];
    } else {
      const tieBreaker =
        options.tieBreaker ??
        ((a, b) => {
          // 기본 tie-breaker:
          // 1. success 우선
          // 2. latency 낮은 쪽 우선
          // 3. content 길이 긴 쪽 우선
          if (a.success !== b.success) return a.success ? a : b;
          if (a.latencyMs !== b.latencyMs) return a.latencyMs < b.latencyMs ? a : b;
          return a.content.length >= b.content.length ? a : b;
        });

      winner = tiedResponses.reduce((best, current) => tieBreaker(best, current));
    }
  }

  return {
    winner,
    scoreboard: sorted,
    allResponses: responses,
  };
