## 3) 기본 scoring rule 예시

실무에서는 보통 아래 기준을 많이 씁니다.

- 성공 여부
- 응답 길이
- 지연 시간(latency)
- 에러 여부
- 금칙어/안전성
- JSON 형식 유효성
- 특정 키워드 포함 여부
- 비용 효율성

예시 구현입니다.

```ts
// scoring-rules.ts

import {
  ProviderRequest,
  ProviderResponse,
  ScoringRule,
} from "./scoreboard-winner";

function isLikelyJson(text: string): boolean {
  try {
    JSON.parse(text);
    return true;
  } catch {
    return false;
  }
}

export const successRule: ScoringRule = {
  name: "success",
  weight: 5,
  evaluate: ({ response }) => {
    if (response.success) {
      return { score: 1, reason: "request succeeded" };
    }
    return { score: 0, reason: `request failed: ${response.error ?? "unknown error"}` };
  },
};

export const latencyRule: ScoringRule = {
  name: "latency",
  weight: 2,
  evaluate: ({ response }) => {
    if (!response.success) {
      return { score: 0, reason: "no latency score because request failed" };
    }

    // 0ms에 가까울수록 좋음. 5000ms 이상이면 거의 0점
    const score = 1 - Math.min(response.latencyMs, 5000) / 5000;
    return { score, reason: `latency=${response.latencyMs}ms` };
  },
};

export const contentLengthRule: ScoringRule = {
  name: "contentLength",
  weight: 1.5,
  evaluate: ({ response }) => {
    if (!response.success || !response.content.trim()) {
      return { score: 0, reason: "empty content" };
    }

    const len = response.content.trim().length;

    // 너무 짧으면 낮은 점수, 200자 이상이면 만점 처리
    const score = Math.min(len / 200, 1);
    return { score, reason: `content length=${len}` };
  },
};

export const noErrorTextRule: ScoringRule = {
  name: "noErrorText",
  weight: 1,
  evaluate: ({ response }) => {
    const lower = response.content.toLowerCase();
    const badPatterns = [
      "i cannot",
      "i can't",
      "error",
      "failed",
      "unavailable",
    ];

    const found = badPatterns.some((p) => lower.includes(p));
    return found
      ? { score: 0.2, reason: "content contains possible failure wording" }
      : { score: 1, reason: "no obvious failure wording" };
  },
};

export const jsonValidityRule: ScoringRule = {
  name: "jsonValidity",
  weight: 3,
  evaluate: ({ request, response }) => {
    // prompt에 JSON 요구가 있을 때만 강하게 평가하는 예시
    const expectsJson = request.prompt.toLowerCase().includes("json");

    if (!expectsJson) {
      return { score: 0.5, reason: "json not explicitly required" };
    }

    if (!response.success || !response.content.trim()) {
      return { score: 0, reason: "empty or failed response" };
    }

    return isLikelyJson(response.content)
      ? { score: 1, reason: "valid JSON" }
      : { score: 0, reason: "invalid JSON" };
  },
};

export const tokenEfficiencyRule: ScoringRule = {
  name: "tokenEfficiency",
  weight: 1,
  evaluate: ({ response }) => {
    if (!response.success || !response.tokenUsage?.total) {
      return { score: 0.5, reason: "token usage unavailable" };
    }

    // total token이 적을수록 좋다고 가정
    const total = response.tokenUsage.total;
    const score = 1 - Math.min(total, 4000) / 4000;
    return { score, reason: `total tokens=${total}` };
  },
};

export const defaultRules: ScoringRule[] = [
  successRule,
  latencyRule,
  contentLengthRule,
  noErrorTextRule,
  jsonValidityRule

