          // 1. success 우선
          // 2. latency 낮은 쪽 우선
          // 3. content 길이 긴 쪽 우선
          if (a.success !== b.success) return a.success ? a : b;
          if (a.latencyMs !== b.latencyMs) return a.latencyMs < b.latencyMs ? a : b;
          return a.content.length >= b.content.length ? a : b;
        });

      winner = tiedResponses.reduce((best, current) => tieBreaker(best, current));
    }
  }

  return {
    winner,
    scoreboard: sorted,
    allResponses: responses,
  };
}
