  if (sorted.length === 0) {
    return {
      winner: null,
      scoreboard: [],
      allResponses: [],
    };
  }

  const top = sorted[0];
  const tied = sorted.filter((s) => s.totalScore === top.totalScore);

  let winner: ProviderResponse | null = null;

  if (tied.length === 1) {
    winner = responseByProvider.get(top.provider) ?? null;
  } else {
    const tiedResponses = tied
      .map((s) => responseByProvider.get(s.provider))
      .filter((r): r is ProviderResponse => Boolean(r));

    if (tiedResponses.length === 0) {
      winner = null;
    } else if (tiedResponses.length === 1) {
      winner = tiedResponses[0];
    } else {
      const tieBreaker =
        options.tieBreaker ??
        ((a, b) => {
          // 기본 tie-breaker:
          // 1. success 우선
          // 2. latency 낮은 쪽 우선
          // 3. content 길이 긴 쪽 우선
          if (a.success !== b.success) return a.success ? a : b;
          if (a.latencyMs !== b.latencyMs) return a.latencyMs < b.latencyMs ? a : b;
          return a.content.length >= b.content.length ? a : b;
        });

      winner = tiedResponses.reduce((best, current) => tieBreaker(best, current));
    }
  }

  return {
    winner,
    scoreboard: sorted,
    allResponses: responses,
  };
}
