import {
  ExecutionResult,
  Plan,
  PlanStep,
  StepExecutionResult
} from "./types.js";
import {
  NonRetryableError,
  RetryableError,
  nowIso,
  retry,
  withTimeout
} from "./utils.js";

export interface Executor {
  execute(plan: Plan): Promise<ExecutionResult>;
}

export class SimpleExecutor implements Executor {
  constructor(
    private readonly options?: {
      stepTimeoutMs?: number;
      retries?: number;
    }
  ) {}

  async execute(plan: Plan): Promise<ExecutionResult> {
    const startedAt = nowIso();
    const results: StepExecutionResult[] = [];

    for (const step of plan.steps) {
      const result = await this.executeStepSafely(step);
      results.push(result);

      // 실패한 step이 있으면 이후 step은 중단
      if (result.status === "failed") {
        break;
      }
    }

    return {
      planId: plan.planId,
      results,
      startedAt,
      endedAt: nowIso()
    };
  }

  private async executeStepSafely(step: PlanStep): Promise<StepExecutionResult> {
    const startedAt = nowIso();

    try {
      const output = await retry(
        () =>
          withTimeout(
            () => this.executeStep(step),
            this.options?.stepTimeoutMs ?? 2000,
            `step:${step.id}`
          ),
        {
          retries: this.options?.retries ?? 1,
          shouldRetry: (error) => error instanceof RetryableError
        }
      );

      return {
        stepId: step.id,
        status: "success",
        startedAt,
        endedAt: nowIso(),
        output
      };
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Unknown execution error";

      return {
        stepId: step.id,
        status: "failed",
        startedAt,
        endedAt: nowIso(),
        error: {
          message,
          retryable: error instanceof RetryableError
        }
      };
    }
  }

  private async executeStep(step: PlanStep): Promise<unknown> {
    switch (step.type) {
      case "validate":
        return this.handleValidate(step);
      case "fetch":
        return this.handleFetch(step);
      case "transform":
        return this.handleTransform(step);
      case "finalize":
        return this.handleFinalize(step);
      default:
        throw new NonRetryableError(`Unsupported step type: ${String(step.type)}`);
    }
  }

  private async handleValidate(step: PlanStep): Promise<unknown> {
    if (!step.description) {
      throw new NonRetryableError("Validation failed: missing description");
    }

    return {
      validated: true
    };
  }

  private async handleFetch(step: PlanStep): Promise<unknown> {
    // 예시용: 간헐적 실패를 발생시켜 retry 동작 확인 가능
    const shouldFailTransiently = Math.random() < 0.3;
    if (shouldFailTransiently) {
      throw new RetryableError("Temporary fetch failure");
    }

    return {
      source: step.payload?.source ?? "unknown",
      items: [
        { id: 1, value: "alpha" },
        { id: 2, value: "beta" }
      ]
    };
  }

  private async handleTransform(_step: PlanStep): Promise<unknown> {
    return {
      transformed: true,
      summary: "2 items transformed"
    };
  }

  private async handleFinalize(_step: PlanStep): Promise<unknown> {
    return {
      completed: true,
      message: "Response packaged successfully"
    };
  }
}
