## 1) Orchestrator 코드

```ts
// ai-orchestrator.ts

export type AIMessage = {
  role: "system" | "user" | "assistant";
  content: string;
};

export type AIRequest = {
  messages: AIMessage[];
  temperature?: number;
  maxTokens?: number;
  signal?: AbortSignal;
  metadata?: Record<string, unknown>;
};

export type AIUsage = {
  promptTokens?: number;
  completionTokens?: number;
  totalTokens?: number;
};

export type AIResponse = {
  provider: string;
  model: string;
  content: string;
  usage?: AIUsage;
  latencyMs: number;
  raw?: unknown;
};

export type AIProviderErrorCode =
  | "TIMEOUT"
  | "RATE_LIMIT"
  | "AUTH"
  | "BAD_REQUEST"
  | "NETWORK"
  | "ABORTED"
  | "PROVIDER_ERROR"
  | "UNKNOWN";

export class AIProviderError extends Error {
  public readonly provider: string;
  public readonly code: AIProviderErrorCode;
  public readonly status?: number;
  public readonly retryable: boolean;
  public readonly cause?: unknown;

  constructor(params: {
    provider: string;
    message: string;
    code: AIProviderErrorCode;
    status?: number;
    retryable?: boolean;
    cause?: unknown;
  }) {
    super(params.message);
    this.name = "AIProviderError";
    this.provider = params.provider;
    this.code = params.code;
    this.status = params.status;
    this.retryable = params.retryable ?? false;
    this.cause = params.cause;
  }
}

export interface AIProvider {
  name: string;
  model: string;
  generate(request: AIRequest): Promise<AIResponse>;
}

export type Logger = {
  info?: (message: string, meta?: Record<string, unknown>) => void;
  warn?: (message: string, meta?: Record<string, unknown>) => void;
  error?: (message: string, meta?: Record<string, unknown>) => void;
};

export type FallbackAttemptResult = {
  provider: string;
  model: string;
  success: boolean;
  latencyMs: number;
  error?: {
    message: string;
    code?: AIProviderErrorCode;
    status?: number;
    retryable?: boolean;
  };
};

export type OrchestratorResult = {
  response: AIResponse;
  attempts: FallbackAttemptResult[];
};

export type OrchestratorOptions = {
  providers: AIProvider[];
  logger?: Logger;
  stopOnNonRetryableError?: boolean;
  perProviderTimeoutMs?: number;
};

function nowMs(): number {
  return Date.now();
}

function isAbortError(err: unknown): boolean {
  return (
    err instanceof Error &&
    (err.name === "AbortError" || err.message.toLowerCase().includes("aborted"))
  );
}

function normalizeUnknownError(provider: string, err: unknown): AIProviderError {
  if (err instanceof AIProviderError) {
    return err;
  }

  if (isAbortError(err)) {
    return new AIProviderError({
      provider,
      message: "Request aborted",
      code: "ABORTED",
      retryable: false,
      cause: err,
    });
  }

  if (err instanceof TypeError) {
    return new AIProviderError({
      provider,
      message: err.message,
      code: "NETWORK",
      retryable: true,
      cause: err,
    });
  }

  if (err instanceof Error) {
    return new AIProviderError({
      provider,
      message: err.message,
      code: "UNKNOWN",
      retryable: false,
      cause: err,
    });
  }

  return new AIProviderError({
    provider,
    message: "Unknown provider error",
    code: "UNKNOWN",
    retryable: false,
    cause: err,
  });
}

async function withTimeout<T>(
  promiseFactory: (signal?: AbortSignal) => Promise<T>,
  timeoutMs: number,
  externalSignal?: AbortSignal,
  providerName?: string
): Promise<T> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);

  const onExternalAbort = () => controller.abort();

  if (externalSignal) {
    if (externalSignal.aborted) {
      controller.abort();
    } else {
      externalSignal.addEventListener("abort", onExternalAbort, { once: true });
    }
  }

  try {
    return await promiseFactory(controller.signal);
  } catch (err) {
    if (controller.signal.aborted && !externalSignal?.aborted) {
      throw new AIProviderError({
        provider: providerName ?? "unknown",
        message: `Provider request timed out after ${timeoutMs}ms`,
        code: "TIMEOUT",
        retryable: true,
        cause: err,
      });
    }
    throw err;
  } finally {
    clearTimeout(timeout);
    if (externalSignal) {
      externalSignal.removeEventListener("abort", onExternalAbort);
    }
  }
}

export async function generateWithFallback(
  request: AIRequest,
  options: OrchestratorOptions
): Promise<OrchestratorResult> {
  const {
    providers,
    logger,
    stopOnNonRetryableError = false,
    perProviderTimeoutMs = 15_000,
  } = options;

  if (!providers.length) {
    throw new Error("At least one provider must be configured");
  }

  const attempts: FallbackAttemptResult[] = [];
  const errors: AIProviderError[] = [];

  for (const provider of providers) {
    const startedAt = nowMs();

    logger?.info?.("ai.provider.attempt", {
      provider: provider.name,
      model: provider.model,
    });

    try {
      const response = await withTimeout(
        (signal) =>
          provider.generate({
            ...request,
            signal,
          }),
        perProviderTimeoutMs,
        request.signal,
        provider.name
      );

      const latencyMs = nowMs() - startedAt;

      attempts.push({
        provider: provider.name,
        model: provider.model,
        success: true,
        latencyMs,
      });

      logger?.info?.("ai.provider.success", {
        provider: provider.name,
        model: provider.model,
        latencyMs,
      });

      return {
        response: {
          ...response,
          latencyMs,
        },
        attempts,
      };
    } catch (err) {
      const normalized = normalizeUnknownError(provider.name, err);
      const latencyMs = nowMs() - startedAt;

      attempts.push({
        provider: provider.name,
        model: provider.model,
        success: false,
        latencyMs,
        error: {
          message: normalized.message,
          code: normalized.code,
          status: normalized.status,
          retryable: normalized.retryable,
        },
      });

      errors.push(normalized);

      logger?.warn?.("ai.provider.failed", {
        provider: provider.name,
        model: provider.model,
        latencyMs,
        error: {
          message: normalized.message,
          code: normalized.code,
          status: normalized.status,
          retryable: normalized.retryable,
        },
      });

      if (normalized.code === "ABORTED") {
        throw normalized;
      }

      if (stopOnNonRetryableError && !normalized.retryable) {
        throw new AggregateError(
          errors,
          "AI generation failed with non-retryable error"
        );
      }
    }
  }

  logger?.error?.("ai.all_providers.failed", { attempts });

  throw new AggregateError(errors, "All AI providers failed");
}
