  request: AIRequest,
  options: OrchestratorOptions
): Promise<OrchestratorResult> {
  const {
    providers,
    logger,
    stopOnNonRetryableError = false,
    perProviderTimeoutMs = 15_000,
  } = options;

  if (!providers.length) {
    throw new Error("At least one provider must be configured");
  }

  const attempts: FallbackAttemptResult[] = [];
  const errors: AIProviderError[] = [];

  for (const provider of providers) {
    const startedAt = nowMs();

    logger?.info?.("ai.provider.attempt", {
      provider: provider.name,
      model: provider.model,
    });

    try {
      const response = await withTimeout(
        (signal) =>
          provider.generate({
            ...request,
            signal,
          }),
        perProviderTimeoutMs,
        request.signal,
        provider.name
      );

      const latencyMs = nowMs() - startedAt;

      attempts.push({
        provider: provider.name,
        model: provider.model,
        success: true,
        latencyMs,
      });

      logger?.info?.("ai.provider.success", {
        provider: provider.name,
        model: provider.model,
        latencyMs,
      });

      return {
        response: {
          ...response,
          latencyMs,
        },
        attempts,
      };
    } catch (err) {
      const normalized = normalizeUnknownError(provider.name, err);
      const latencyMs = nowMs() - startedAt;

      attempts.push({
        provider: provider.name,
        model: provider.model,
        success: false,
        latencyMs,
        error: {
          message: normalized.message,
          code: normalized.code,
          status: normalized.status,
          retryable: normalized.retryable,
        },
      });

      errors.push(normalized);

      logger?.warn?.("ai.provider.failed", {
        provider: provider.name,
        model: provider.model,
        latencyMs,
        error: {
          message: normalized.message,
          code: normalized.code,
          status: normalized.status,
          retryable: normalized.retryable,
        },
      });

      if (normalized.code === "ABORTED") {
        throw normalized;
      }

      if (stopOnNonRetryableError && !normalized.retryable) {
        throw new AggregateError(
          errors,
          "AI generation failed with non-retryable error"
        );
      }
    }
  }

  logger?.error?.("ai.all_providers.failed", { attempts });

  throw new AggregateError(errors, "All AI providers failed");
}
