  latencyMs?: number;
  tokenUsage?: {
    input?: number;
    output?: number;
    total?: number;
  };
}

export interface JudgeInput {
  userPrompt: string;
  systemPrompt?: string;
  expectedFormat?: ExpectedFormat;
  candidates: [CandidateResponse, CandidateResponse];
  metadata?: {
    taskType?: TaskType;
    requireCitations?: boolean;
    maxPreferredLength?: number;
  };
}

export interface ScoreBreakdown {
  instructionFollowing: number; // 0~1
  completeness: number;         // 0~1
  correctness: number;          // 0~1
  safety: number;               // 0~1
  formatQuality: number;        // 0~1
  conciseness: number;          // 0~1
  groundedness: number;         // 0~1
}

export interface CandidateEvaluation {
  provider: ModelProvider;
  model: string;
  totalScore: number;   // 0~1
  confidence: number;   // 0~1
  breakdown: ScoreBreakdown;
  reasons: string[];
  warnings: string[];
}

export interface JudgeDecision {
  winner: ModelProvider | 'tie';
  winnerModel?: string;
