# 3. 구현 코드

아래 코드는 **운영 가능한 baseline judge**입니다.

```ts
export type ModelProvider = 'openai' | 'claude';
export type ExpectedFormat = 'text' | 'json' | 'markdown' | 'code';
export type TaskType = 'qa' | 'coding' | 'summarization' | 'analysis' | 'chat';

export interface CandidateResponse {
  provider: ModelProvider;
  model: string;
  content: string;
  latencyMs?: number;
  tokenUsage?: {
    input?: number;
    output?: number;
    total?: number;
  };
}

export interface JudgeInput {
  userPrompt: string;
  systemPrompt?: string;
  expectedFormat?: ExpectedFormat;
  candidates: [CandidateResponse, CandidateResponse];
  metadata?: {
    taskType?: TaskType;
    requireCitations?: boolean;
    maxPreferredLength?: number;
  };
}

export interface ScoreBreakdown {
  instructionFollowing: number;
  completeness: number;
  correctness: number;
  safety: number;
  formatQuality: number;
  conciseness: number;
  groundedness: number;
}

export interface CandidateEvaluation {
  provider: ModelProvider;
  model: string;
  totalScore: number;
  confidence: number;
  breakdown: ScoreBreakdown;
  reasons: string[];
  warnings: string[];
}

export interface JudgeDecision {
  winner: ModelProvider | 'tie';
  winnerModel?: string;
  evaluations: CandidateEvaluation[];
  method: 'rule-based' | 'llm-judge' | 'hybrid';
  rationale: string;
  audit: {
    judgedAt: string;
    version: string;
    ambiguous: boolean;
  };
}

const JUDGE_VERSION = '1.0.0';

const WEIGHTS: Record<keyof ScoreBreakdown, number> = {
  instructionFollowing: 0.25,
  completeness: 0.15,
  correctness: 0.20,
  safety: 0.15,
  formatQuality: 0.10,
  conciseness: 0.05,
  groundedness: 0.10,
};

export function judgeResponses(input: JudgeInput): JudgeDecision {
  const evaluations = input.candidates.map((candidate) =>
    evaluateCandidate(candidate, input)
  );

  const [a, b] = evaluations;
  const diff = Math.abs(a.totalScore - b.totalScore);
  const ambiguous = diff < 0.08;

  if (!ambiguous) {
    const best = a.totalScore >= b.totalScore ? a : b;
    const other = best === a ? b : a;

    return {
      winner: best.provider,
      winnerModel: best.model,
      evaluations,
      method: 'rule-based',
      rationale: `${best.provider} selected by higher rule-based score (${best.totalScore.toFixed(
        3
      )} vs ${other.totalScore.toFixed(3)}).`,
      audit: {
        judgedAt: new Date().toISOString(),
        version: JUDGE_VERSION,
        ambiguous: false,
      },
    };
  }

  return {
    winner: 'tie',
    evaluations,
    method: 'rule-based',
    rationale: `Scores are too close (${a.totalScore.toFixed(3)} vs ${b.totalScore.toFixed(
      3
    )}); escalate to LLM judge.`,
    audit: {
      judgedAt: new Date().toISOString(),
      version: JUDGE_VERSION,
      ambiguous: true,
    },
  };
}

function evaluateCandidate(
  candidate: CandidateResponse,
  input: JudgeInput
): CandidateEvaluation {
  const content = normalizeText(candidate.content);
  const reasons: string[] = [];
  const warnings: string[] = [];

  const breakdown: ScoreBreakdown = {
    instructionFollowing: scoreInstructionFollowing(content, input, reasons, warnings),
    completeness: scoreCompleteness(content, input, reasons),
    correctness: scoreCorrectnessHeuristic(content, input, reasons, warnings),
    safety: scoreSafety(content, reasons, warnings),
    formatQuality: scoreFormat(content, input, reasons, warnings),
    conciseness: scoreConciseness(content, input, reasons),
    groundedness: scoreGroundedness(content, input, reasons, warnings),
  };

  const totalScore = weightedScore(breakdown);
  const confidence = estimateConfidence(breakdown, warnings);

  return {
    provider: candidate.provider,
    model: candidate.model,
    totalScore,
    confidence,
    breakdown,
    reasons,
    warnings,
  };
}

function weightedScore(breakdown: ScoreBreakdown): number {
  const total = (Object.keys(WEIGHTS) as (keyof ScoreBreakdown)[]).reduce(
    (sum, key) => sum + breakdown[key] * WEIGHTS[key],
    0
  );
  return round(total);
}

function estimateConfidence(
  breakdown: ScoreBreakdown,
  warnings: string[]
): number {
  const values = Object.values(breakdown);
  const avg = values.reduce((a, b) => a + b, 0) / values.length;
  const warningPenalty = Math.min(warnings.length * 0.08, 0.30);
  return round(clamp01(avg - warningPenalty));
}

function normalizeText(text: string): string {
  return text.replace(/\r\n/g, '\n').replace(/\t/g, '  ').trim();
}

function scoreInstructionFollowing(
  content: string,
  input: JudgeInput,
  reasons: string[],
  warnings: string[]
): number {
  let score = 0.45;
  const prompt = input.userPrompt.toLowerCase();
  const text = content.toLowerCase();

  if (content.length > 0) score += 0.10;

  const promptKeywords = extractKeywords(prompt);
  const matched = promptKeywords.filter((kw) => text.includes(kw)).length;
