# 1차 Rule-based Judge 구현

아래 코드는 **운영 가능한 기본형**입니다.  
완전히 “정답 판별”은 못 하지만, 실제 서비스에서 꽤 유용한 baseline입니다.

```ts
type ModelProvider = 'openai' | 'claude';

interface CandidateResponse {
  provider: ModelProvider;
  model: string;
  content: string;
  latencyMs?: number;
  tokenUsage?: {
    input?: number;
    output?: number;
    total?: number;
  };
}

interface JudgeInput {
  userPrompt: string;
  systemPrompt?: string;
  expectedFormat?: 'text' | 'json' | 'markdown' | 'code';
  candidates: [CandidateResponse, CandidateResponse];
  metadata?: {
    taskType?: 'qa' | 'coding' | 'summarization' | 'analysis' | 'chat';
    requireCitations?: boolean;
    maxPreferredLength?: number;
  };
}

interface ScoreBreakdown {
  instructionFollowing: number;
  completeness: number;
  correctness: number;
  safety: number;
  formatQuality: number;
  conciseness: number;
  groundedness: number;
}

interface CandidateEvaluation {
  provider: ModelProvider;
  model: string;
  totalScore: number;
  confidence: number;
  breakdown: ScoreBreakdown;
  reasons: string[];
  warnings: string[];
}

interface JudgeDecision {
  winner: ModelProvider | 'tie';
  winnerModel?: string;
  evaluations: CandidateEvaluation[];
  method: 'rule-based' | 'llm-judge' | 'hybrid';
  rationale: string;
  audit: {
    judgedAt: string;
    version: string;
    ambiguous: boolean;
  };
}

const JUDGE_VERSION = '1.0.0';

const WEIGHTS: Record<keyof ScoreBreakdown, number> = {
  instructionFollowing: 0.25,
  completeness: 0.15,
  correctness: 0.2,
  safety: 0.15,
  formatQuality: 0.1,
  conciseness: 0.05,
  groundedness: 0.1,
};

export function judgeResponses(input: JudgeInput): JudgeDecision {
  const evaluations = input.candidates.map((candidate) =>
    evaluateCandidate(candidate, input)
  );

  const [a, b] = evaluations;
  const diff = Math.abs(a.totalScore - b.totalScore);
  const ambiguous = diff < 0.08;

  let winner: ModelProvider | 'tie' = 'tie';
  let winnerModel: string | undefined;
  let rationale = '';

  if (!ambiguous) {
    const best = a.totalScore > b.totalScore ? a : b;
    winner = best.provider;
    winnerModel = best.model;
    rationale = `${best.provider} selected by higher rule-based score (${best.totalScore.toFixed(3)} vs ${
      (best === a ? b.totalScore : a.totalScore).toFixed(3)
    }).`;
  } else {
    rationale = `Scores are too close (${a.totalScore.toFixed(3)} vs ${b.totalScore.toFixed(3)}); tie or escalate to LLM judge.`;
  }

  return {
    winner,
    winnerModel,
    evaluations,
    method: 'rule-based',
    rationale,
    audit: {
      judgedAt: new Date().toISOString(),
      version: JUDGE_VERSION,
      ambiguous,
    },
  };
}

function evaluateCandidate(
  candidate: CandidateResponse,
  input: JudgeInput
): CandidateEvaluation {
  const content = normalizeText(candidate.content);
  const reasons: string[] = [];
  const warnings: string[] = [];

  const breakdown: ScoreBreakdown = {
    instructionFollowing: scoreInstructionFollowing(content, input, reasons, warnings),
    completeness: scoreCompleteness(content, input, reasons),
    correctness: scoreCorrectnessHeuristic(content, input, reasons, warnings),
    safety: scoreSafety(content, warnings),
    formatQuality: scoreFormat(content, input, reasons, warnings),
    conciseness: scoreConciseness(content, input, reasons),
    groundedness: scoreGroundedness(content, input, reasons, warnings),
  };

  const totalScore = weightedScore(breakdown);
  const confidence = estimateConfidence(breakdown, warnings);

  return {
    provider: candidate.provider,
    model: candidate.model,
    totalScore,
    confidence,
    breakdown,
    reasons,
    warnings,
  };
}

function weightedScore(breakdown: ScoreBreakdown): number {
  const total = (Object.keys(WEIGHTS) as (keyof ScoreBreakdown)[])
    .reduce((sum, key) => sum + breakdown[key] * WEIGHTS[key], 0);
  return round(total);
}

function estimateConfidence(
  breakdown: ScoreBreakdown,
  warnings: string[]
