output.answer_text:
아래는 **scoreboard 기반으로 여러 provider 응답을 평가하고 최종 winner를 반환하는 TypeScript 코드**입니다.  
실무에서 바로 확장할 수 있도록 **타임아웃, 실패 처리, 가중치, 점수 상세 breakdown**까지 포함했습니다.

```ts
/* eslint-disable no-console */

type ProviderName = "openai" | "anthropic" | "google" | "custom";

interface ProviderRequest {
  prompt: string;
  timeoutMs?: number;
}

interface ProviderResponse {
  provider: ProviderName;
  content: string;
  confidence?: number; // 0 ~ 1
  latencyMs: number;
  success: boolean;
  error?: string;
  metadata?: Record<string, unknown>;
}

interface Provider {
  name: ProviderName;
  weight?: number; // provider별 기본 가중치
  generate(request: ProviderRequest): Promise<ProviderResponse>;
}

interface ScoreBreakdown {
  baseScore: number;
  latencyScore: number;
  confidenceScore: number;
  contentLengthScore: number;
  successScore: number;
  errorPenalty: number;
  providerWeightBonus: number;
  totalScore: number;
  reasons: string[];
}

interface ScoredProviderResponse {
  response: ProviderResponse;
  score: ScoreBreakdown;
}

interface WinnerResult {
  winner: ScoredProviderResponse | null;
  ranked: ScoredProviderResponse[];
  summary: {
    totalProviders: number;
    successfulProviders: number;
    failedProviders: number;
  };
}

interface ScoreConfig {
  successBaseScore: number;
  failureBaseScore: number;
  maxLatencyMs: number;
  latencyWeight: number;
  confidenceWeight: number;
  contentLengthWeight: number;
  successWeight: number;
  errorPenaltyWeight: number;
  providerWeightMultiplier: number;
  minUsefulContentLength: number;
  maxUsefulContentLength: number;
}

const defaultScoreConfig: ScoreConfig = {
  successBaseScore: 50,
  failureBaseScore: 0,
  maxLatencyMs: 10_000,
  latencyWeight: 20,
  confidenceWeight: 20,
  contentLengthWeight: 10,
  successWeight: 20,
  errorPenaltyWeight: 30,
  providerWeightMultiplier: 10,
  minUsefulContentLength: 20,
  maxUsefulContentLength: 1000,
};

function clamp(value: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, value));
}

function normalizeContentLength(
  content: string,
  minLength: number,
  maxLength: number
): number {
  const len = content.trim().length;
  if (len <= minLength) return 0;
  if (len >= maxLength) return 1;
  return (len - minLength) / (maxLength - minLength);
}

function scoreResponse(
  response: ProviderResponse,
  providerWeight: number = 1,
  config: ScoreConfig = defaultScoreConfig
): ScoreBreakdown {
  const reasons: string[] = [];

  const baseScore = response.success
    ? config.successBaseScore
    : config.failureBaseScore;

  reasons.push(
    response.success
      ? `success base score +${baseScore}`
      : `failure base score +${baseScore}`
  );

  const latencyRatio = 1 - clamp(response.latencyMs / config.maxLatencyMs, 0, 1);
  const latencyScore = latencyRatio * config.latencyWeight;
  reasons.push(
    `latency ${response.latencyMs}ms => +${latencyScore.toFixed(2)}`
  );

  const confidence = clamp(response.confidence ?? 0.5, 0, 1);
  const confidenceScore = confidence * config.confidenceWeight;
  reasons.push(
    `confidence ${confidence.toFixed(2)} => +${confidenceScore.toFixed(2)}`
  );

  const contentLengthRatio = normalizeContentLength(
    response.content,
    config.minUsefulContentLength,
    config.maxUsefulContentLength
  );
  const contentLengthScore = contentLengthRatio * config.contentLengthWeight;
  reasons.push(
    `content length ${response.content.trim().length} => +${contentLengthScore.toFixed(2)}`
  );

  const successScore = response.success ? config.successWeight : 0;
  reasons.push(`success bonus +${successScore.toFixed(2)}`);

  const errorPenalty = response.error ? config.errorPenaltyWeight : 0;
  if (response.error) {
    reasons.push(`error penalty -${errorPenalty.toFixed(2)} (${response.error})`);
  }

  const providerWeightBonus = providerWeight * config.providerWeightMultiplier;
  reasons.push(
    `provider weight ${providerWeight.toFixed(2)} => +${providerWeightBonus.toFixed(2)}`
  );

  const totalScore =
    baseScore +
    latencyScore +
    confidenceScore +
    contentLengthScore +
    successScore +
    providerWeightBonus -
    errorPenalty;

  return {
    baseScore,
    latencyScore,
    confidenceScore,
    contentLengthScore,
    successScore,
    errorPenalty,
    providerWeightBonus,
    totalScore,
    reasons,
  };
}

async function withTimeout<T>(
  promise: Promise<T>,
  timeoutMs: number,
  message: string
): Promise<T> {
  let timeoutHandle: ReturnType<typeof setTimeout> | undefined;

  const timeoutPromise = new Promise<T>((_, reject) => {
    timeoutHandle = setTimeout(() => {
      reject(new Error(message));
    }, timeoutMs);
  });

  try {
    return await Promise.race([promise, timeoutPromise]);
  } finally {
    if (timeoutHandle) clearTimeout(timeoutHandle);
  }
}

async function executeProvider(
  provider: Provider,
  request: ProviderRequest
): Promise<ProviderResponse> {
  const startedAt = Date.now();
  const timeoutMs = request.timeoutMs ?? 5000;

  try {
    const response = await withTimeout(
      provider.generate(request),
      timeoutMs,
      `Provider ${provider.name} timed out after ${timeoutMs}ms`
    );

    return {
      ...response,
      provider: provider.name,
      latencyMs: response.latencyMs || Date.now() - startedAt,
    };
  } catch (error) {
    return {
      provider: provider.name,
      content: "",
      confidence: 0,
      latencyMs: Date.now() - startedAt,
      success: false,
      error: error instanceof Error ? error.message : "Unknown error",
    };
  }
}

async function evaluateProviders(
  providers: Provider[],
  request: ProviderRequest,
  config: ScoreConfig = defaultScoreConfig
): Promise<WinnerResult> {
  const responses = await Promise.all(
    providers.map((provider) => executeProvider(provider, request))
  );

  const scored: ScoredProviderResponse[] = responses.map((response) => {
    const provider = providers.find((p) => p.name === response.provider);
    const weight = provider?.weight ?? 1;

    return {
      response,
      score: scoreResponse(response, weight, config),
    };
  });

  scored.sort((a, b) => b.score.totalScore - a.score.totalScore);

  return {
    winner: scored[0] ?? null,
    ranked: scored,
    summary: {
      totalProviders: scored.length,
      successfulProviders: scored.filter((r) => r.response.success).length,
      failedProviders: scored.filter((r) => !r.response.success).length,
    },
  };
}
```

## Mock Provider 예시

```ts
function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

class MockProvider implements Provider {
  public name: ProviderName;
  public weight?: number;

  private mockLatencyMs: number;
  private mockContent: string;
  private mockConfidence: number;
  private shouldFail: boolean;

  constructor(params: {
    name: ProviderName;
    weight?: number;
    mockLatencyMs: number;
    mockContent: string;
    mockConfidence: number;
    shouldFail?: boolean;
  }) {
    this.name = params.name;
    this.weight = params.weight;
    this.mockLatencyMs = params.mockLatencyMs;
    this.mockContent = params.mockContent;
    this.mockConfidence = params.mockConfidence;
    this.shouldFail = params.shouldFail ?? false;
  }

  async generate(_request: ProviderRequest): Promise<ProviderResponse> {
    await sleep(this.mockLatencyMs);

    if (this.shouldFail) {
      throw new Error(`${this.name} provider failed`);
    }

    return {
      provider: this.name,
      content: this.mockContent,
      confidence: this.mockConfidence,
      latencyMs: this.mockLatencyMs,
      success: true,
      metadata: {
        model: `${this.name}-model-v1`,
      },
    };
  }
}
```

