# 4) 공통 타입: src/types.ts

```ts
export type TaskInput = {
  requestId: string;
  userGoal: string;
  context?: Record<string, unknown>;
};

export type PlanStepType = "validate" | "transform" | "compute" | "finalize";

export type PlanStep = {
  id: string;
  type: PlanStepType;
  description: string;
  payload?: Record<string, unknown>;
};

export type Plan = {
  planId: string;
  steps: PlanStep[];
  metadata?: Record<string, unknown>;
};

export type StepExecutionStatus = "success" | "failed" | "skipped";

export type StepExecutionResult = {
  stepId: string;
  status: StepExecutionStatus;
  startedAt: string;
  finishedAt: string;
  output?: unknown;
  error?: {
    message: string;
    retryable: boolean;
  };
};

export type ExecutionResult = {
  planId: string;
  results: StepExecutionResult[];
  startedAt: string;
  finishedAt: string;
};

export type JudgeDecision = "approved" | "rejected" | "needs_retry";

export type JudgeResult = {
  decision: JudgeDecision;
  score: number;
  reasons: string[];
};

export type OrchestrationStatus = "completed" | "failed";

export type OrchestrationResult = {
  requestId: string;
  status: OrchestrationStatus;
  plan: Plan;
  execution: ExecutionResult;
  judge: JudgeResult;
};

export type OrchestratorOptions = {
  maxExecutionRetries: number;
  stepTimeoutMs: number;
};
```

