# 7) Planner: src/planner.ts

여기서는 입력을 바탕으로 단순한 plan을 생성합니다.  
실무에서는 이 부분을 LLM 호출, 규칙 엔진, 정책 기반 플래너로 바꿀 수 있습니다.

```ts
import { Plan, PlanStep, TaskInput } from "./types";

export interface Planner {
  createPlan(input: TaskInput): Promise<Plan>;
}

export class SimplePlanner implements Planner {
  async createPlan(input: TaskInput): Promise<Plan> {
    const steps: PlanStep[] = [
      {
        id: "step-1",
        type: "validate",
        description: "Validate user goal and input context",
        payload: {
          userGoal: input.userGoal
        }
      },
      {
        id: "step-2",
        type: "transform",
        description: "Normalize and transform the goal into executable form",
        payload: {
          normalizedGoal: input.userGoal.trim().toLowerCase()
        }
      },
      {
        id: "step-3",
        type: "compute",
        description: "Perform the main computation",
        payload: {
          strategy: "simple"
        }
      },
      {
        id: "step-4",
        type: "finalize",
        description: "Finalize and summarize the result"
      }
    ];

    return {
      planId: `plan-${input.requestId}`,
      steps,
      metadata: {
        source: "SimplePlanner"
      }
    };
  }
}
```

