# 8) Executor: src/executor.ts

각 step을 순차 실행합니다.  
실패 시 step 단위 결과를 남기고, retry/timeout을 적용합니다.

```ts
import {
  ExecutionResult,
  OrchestratorOptions,
  Plan,
  PlanStep,
  StepExecutionResult
} from "./types";
import { Logger } from "./logger";
import { retry, toErrorMessage, withTimeout, sleep } from "./utils";

export interface Executor {
  execute(plan: Plan, options: OrchestratorOptions): Promise<ExecutionResult>;
}

export class SimpleExecutor implements Executor {
  constructor(private readonly logger: Logger) {}

  async execute(plan: Plan, options: OrchestratorOptions): Promise<ExecutionResult> {
    const startedAt = new Date().toISOString();
    const results: StepExecutionResult[] = [];

    for (const step of plan.steps) {
      this.logger.info("Executing step", {
        planId: plan.planId,
        stepId: step.id,
        stepType: step.type
      });

      const stepStartedAt = new Date().toISOString();

      try {
        const output = await retry(
          () =>
            withTimeout(
              () => this.runStep(step),
              options.stepTimeoutMs,
              `Step ${step.id} timed out`
            ),
          {
            retries: options.maxExecutionRetries,
            shouldRetry: (error) => {
              const message = toErrorMessage(error);
              return !message.includes("Validate failed");
            },
            backoffMs: 200
          }
        );

        results.push({
          stepId: step.id,
          status: "success",
          startedAt: stepStartedAt,
          finishedAt: new Date().toISOString(),
          output
        });
      } catch (error) {
        const message = toErrorMessage(error);

        this.logger.error("Step execution failed", {
          planId: plan.planId,
          stepId: step.id,
          error: message
        });

        results.push({
          stepId: step.id,
          status: "failed",
          startedAt: stepStartedAt,
          finishedAt: new Date().toISOString(),
          error: {
            message,
            retryable: !message.includes("Validate failed")
          }
        });

        // 간단한 오케스트레이션 예시에서는 실패 시 이후 step은 skip 처리
        const remainingSteps = plan.steps.slice(results.length);
        for (const remainingStep of remainingSteps) {
          results.push({
            stepId: remainingStep.id,
            status: "skipped",
            startedAt: new Date().toISOString(),
            finishedAt: new Date().toISOString(),
            error: {
              message: "Skipped due to previous failure",
              retryable: false
            }
          });
        }

        break;
      }
    }

    return {
      planId: plan.planId,
      results,
      startedAt,
      finishedAt: new Date().toISOString()
    };
  }

  private async runStep(step: PlanStep): Promise<unknown> {
    switch (step.type) {
      case "validate":
        return this.handleValidate(step);
      case "transform":
        return this.handleTransform(step);
